@minpoly.exists_algEquiv_of_root : ∀ {K : Type u_1} {L : Type u_2} [inst : Field K] [inst_1 : Field L]
  [inst_2 : Algebra K L] [Normal K L] {x y : L}, IsAlgebraic K y → (aeval x) (minpoly K y) = 0 → ∃ σ, σ x = y
@card_rootSet_eq_natDegree : ∀ {F : Type u_1} [inst : Field F] {K : Type u_2} [inst_1 : Field K] [inst_2 : Algebra F K]
  {p : F[X]}, p.Separable → (map (algebraMap F K) p).Splits → Fintype.card ↑(p.rootSet K) = p.natDegree
@Gal.galAction_isPretransitive : ∀ {F : Type u_1} [inst : Field F] (p : F[X]) (E : Type u_2) [inst_1 : Field E]
  [inst_2 : Algebra F E] [inst_3 : Fact (map (algebraMap F E) p).Splits],
  Irreducible p → MulAction.IsPretransitive p.Gal ↑(p.rootSet E)
@Gal.card_of_separable : ∀ {F : Type u_1} [inst : Field F] {p : F[X]},
  p.Separable → Nat.card p.Gal = Module.finrank F p.SplittingField

